/* oxlint-disable @typescript-eslint/no-explicit-any */
import { assertSyncResult, ValidationFailed } from '@wskit/core';
import type { StandardSchemaV1 } from '@standard-schema/spec';
import type * as EngineRuntimeTypes from '~/_engine/runtime/types.ts';
import type * as ChannelPrimitive from '~/channel/channel.ts';
import type * as NamespacePrimitive from '~/namespace/namespace.ts';
import type * as PrimitiveCore from '~/primitive.ts';

/**
 * Event names reserved for the wskit wire protocol. These are consumed
 * directly by the engine's protocol switch (incoming) or generated by the
 * engine for protocol traffic (outgoing). Defining your own event with one
 * of these names either makes your handler unreachable or lets your code
 * spoof framework frames — both rejected at declaration time and at
 * server compile time.
 */
export const RESERVED_EVENT_NAMES: ReadonlySet<string> = new Set([
  'ping',
  'pong',
  '_ack',
  '_error',
  '_replay',
  '_subscribe',
  '_subscribeOk',
  '_unsubscribe',
  '_kicked',
  '_memberJoin',
  '_memberLeave',
  '_memberOnline',
  '_memberOffline',
  '_streamOk',
  '_streamEnd',
  '_streamCancel',
]);

/**
 * Narrow a primitive to a namespace block.
 */
export function isNamespacePrimitive(
  primitive: PrimitiveCore.Primitive,
): primitive is NamespacePrimitive.NamespacePrimitive {
  return primitive.__wskit === 'namespace';
}

/**
 * Narrow a primitive to a channel block.
 */
export function isChannelPrimitive(
  primitive: PrimitiveCore.Primitive,
): primitive is ChannelPrimitive.ChannelPrimitive {
  return primitive.__wskit === 'channel';
}

/**
 * Merge primitive dependency requirements into one runtime manifest.
 */
export function mergeRequires(
  target: PrimitiveCore.RequiresManifest,
  source: PrimitiveCore.RequiresManifest,
): void {
  if (source.storage) target.storage = true;
  if (source.timers) target.timers = true;
  if (source.hibernation) target.hibernation = true;
}

function isStandardSchema(v: unknown): v is StandardSchemaV1 {
  return (
    !!v &&
    typeof v === 'object' &&
    '~standard' in v &&
    typeof (v as Record<string, any>)['~standard']?.validate === 'function'
  );
}

/**
 * Run a validator or standard-schema object and normalize the result.
 *
 * This lets the engine accept plain validator functions and schema libraries
 * that expose the Standard Schema interface.
 */
export function validateValue(validator: unknown, value: unknown, event = 'unknown'): unknown {
  if (!validator) return value;

  if (typeof validator === 'function') {
    return assertSyncResult(validator(value), event);
  }

  if (isStandardSchema(validator)) {
    const result = assertSyncResult(validator['~standard'].validate(value), event);

    if (result && typeof result === 'object' && 'issues' in result) {
      const rawIssues = (result as { issues: Array<{ message: string; path?: unknown[] }> }).issues;
      throw ValidationFailed({
        event,
        issues: rawIssues.map((issue) => {
          const normalized: { message: string; path?: Array<string | number> } = {
            message: issue.message,
          };
          if (Array.isArray(issue.path)) {
            const pathKeys = issue.path.flatMap((p) => {
              if (typeof p === 'string' || typeof p === 'number') return [p];
              if (p && typeof p === 'object' && 'key' in (p as object)) {
                const k = (p as { key: unknown }).key;
                if (typeof k === 'string' || typeof k === 'number') return [k];
              }
              return [];
            });
            if (pathKeys.length > 0) normalized.path = pathKeys;
          }
          return normalized;
        }),
      });
    }

    if (result && typeof result === 'object' && 'value' in result) {
      return (result as { value: unknown }).value;
    }

    return result;
  }

  return value;
}

/**
 * Reserved keys the engine uses on the wire for routing, correlation, and
 * delivery bookkeeping. They are stripped from incoming payloads before user
 * validators or handlers see them, so application schemas (including strict
 * ones) can describe only the app data and handler functions never observe
 * private transport fields as if they were domain values.
 */
export const PROTOCOL_PAYLOAD_FIELDS: ReadonlySet<string> = new Set([
  '_channel',
  '_channelScope',
  '_namespace',
  '_correlationId',
  '_ackId',
  '_messageId',
  '_seq',
  '_streamId',
]);

/**
 * Return a shallow copy of `payload` with every reserved transport key
 * removed. Non-object payloads are returned unchanged so primitive payloads
 * (numbers, strings, arrays) flow through untouched.
 */
export function stripProtocolFields(payload: unknown): unknown {
  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return payload;
  const source = payload as Record<string, unknown>;
  const cleaned: Record<string, unknown> = {};
  for (const key of Object.keys(source)) {
    if (key === '__proto__') continue;
    if (PROTOCOL_PAYLOAD_FIELDS.has(key)) continue;
    cleaned[key] = source[key];
  }
  return cleaned;
}

/**
 * Reserve a private wire event name for a module-owned event.
 */
export function prefixedModuleEvent(moduleId: string, event: string): string {
  return `__${moduleId}:${event}`;
}

/**
 * Reserve single-underscore event names for engine protocol traffic.
 *
 * Double-underscore names are module-owned outgoing events, not protocol
 * events, so they still participate in normal outgoing features like
 * sequence and dedup.
 */
export function isProtocolEvent(event: string): boolean {
  return event.startsWith('_') && !event.startsWith('__');
}

/**
 * True when `event` is one of the wire's named protocol events.
 *
 * Used by the wire-send declaration check so user code cannot emit any
 * single-underscore name except the ones the engine actually recognises.
 * The single source of truth for this list is `RESERVED_EVENT_NAMES`
 * in `~/event.ts` — extending the wire protocol means adding the new
 * name there, and this check picks it up automatically.
 */
export function isEngineOutgoingProtocolEvent(event: string): boolean {
  return RESERVED_EVENT_NAMES.has(event);
}

/**
 * Narrow one event name to the set of protocol messages the client is allowed
 * to send into the engine.
 */
export function isIncomingProtocolEvent(
  event: string,
): event is EngineRuntimeTypes.IncomingProtocolEvent {
  return (
    event === 'ping' ||
    event === '_subscribe' ||
    event === '_unsubscribe' ||
    event === '_streamCancel' ||
    event === '_replay'
  );
}
